from decimal import Decimal, ROUND_HALF_EVEN

def invoice_total(lines, discount="0"):
    total = Decimal(0)
    for price, quantity in lines:
        if quantity < 0: raise ValueError("negative quantity")
        total += Decimal(str(price)) * Decimal(str(quantity))
    return (total * (1-Decimal(str(discount)))).quantize(Decimal("0.01"), rounding=ROUND_HALF_EVEN)

