def page(rows, cursor, limit):
    if limit <= 0: raise ValueError("nonpositive limit")
    ordered = sorted(rows, key=lambda row: (row["timestamp"],row["id"]))
    return [row for row in ordered if cursor is None or (row["timestamp"],row["id"])>cursor][:limit]

