from dataclasses import dataclass
import math
@dataclass(frozen=True)
class Settings:
    max_attempts: int=3
    base_delay: float=1
    cap_delay: float=8
    def __post_init__(self):
        if not isinstance(self.max_attempts,int) or not 1<=self.max_attempts<=8: raise ValueError("attempt bound")
        if not math.isfinite(self.base_delay) or self.base_delay<0: raise ValueError("base bound")
        if not math.isfinite(self.cap_delay) or self.cap_delay<=0: raise ValueError("cap bound")

