class RetryableError(Exception): pass

def run(operation, settings, sleep):
    for attempt in range(settings.max_attempts):
        try: return operation()
        except RetryableError:
            if attempt+1 == settings.max_attempts: raise
            sleep(min(settings.cap_delay, settings.base_delay * 2**attempt))

