from pathlib import Path
import hashlib
class FileCache:
    def __init__(self): self.entries={}
    def read(self,path):
        path=Path(path); data=path.read_bytes(); digest=hashlib.sha256(data).digest()
        if path not in self.entries or self.entries[path][0]!=digest: self.entries[path]=(digest,data.decode("utf-8"))
        return self.entries[path][1]

