import json

def import_log(text):
    rows=[];seen=set()
    for line in text.splitlines():
        if not line.strip(): continue
        row=json.loads(line)
        if not isinstance(row,dict) or not isinstance(row.get("id"),str) or not row["id"] or row["id"] in seen: raise ValueError("invalid id")
        seen.add(row["id"]);rows.append(row)
    return rows

