class Budget:
    def __init__(self,limit):
        if limit<0: raise ValueError("limit")
        self.limit=limit;self.used=0
    def reserve(self,n):
        if n<0: raise ValueError("reservation")
        if self.used+n>self.limit: return False
        self.used+=n;return True
    def release(self,n):
        if n<0 or n>self.used: raise ValueError("release")
        self.used-=n

